import { randomBytes } from "node:crypto";

export type Curation = "curated" | "raw-excerpt" | "session-excerpt" | "heading-section";

export type NodeKind = "page" | "section";

export interface EnvelopeChunk {
  source: string;
  line_range: [number, number];
  curation: Curation;
  text: string;
  node_id?: string;
  heading_path?: string[];
  node_kind?: NodeKind;
}

export interface EnvelopePolicy {
  trust?: "curated" | "raw";
  source_scope?: "wiki" | "raw" | "sessions";
  no_results?: boolean;
  suggestions?: string[];
  tree_root?: string;
  nav_trace?: string[];
  [key: string]: unknown;
}

export interface Envelope {
  schema_version: "2";
  nonce: string;
  policy: EnvelopePolicy;
  chunks: EnvelopeChunk[];
}

export interface BuildEnvelopeInput {
  policy: EnvelopePolicy;
  chunks: EnvelopeChunk[];
}

export function buildEnvelope(input: BuildEnvelopeInput): Envelope {
  return {
    schema_version: "2",
    nonce: randomBytes(16).toString("hex"),
    policy: input.policy,
    chunks: input.chunks,
  };
}

export function writeEnvelope(envelope: Envelope): string {
  const body = JSON.stringify(envelope);
  const bytes = new TextEncoder().encode(body).length;
  return `${bytes}\n${body}`;
}

export class EnvelopeVersionError extends Error {
  constructor(public readonly version: unknown) {
    super(`envelope: unsupported schema_version: ${String(version)}`);
    this.name = "EnvelopeVersionError";
  }
}

function assertValidShape(parsed: unknown): asserts parsed is Envelope {
  if (!parsed || typeof parsed !== "object") {
    throw new Error("envelope: body is not an object");
  }
  const p = parsed as Record<string, unknown>;
  if (p.schema_version !== "2") {
    throw new EnvelopeVersionError(p.schema_version);
  }
  if (typeof p.nonce !== "string" || !/^[0-9a-f]{32}$/.test(p.nonce)) {
    throw new Error("envelope: nonce must be 32-hex string");
  }
  if (!p.policy || typeof p.policy !== "object") {
    throw new Error("envelope: policy must be an object");
  }
  if (!Array.isArray(p.chunks)) {
    throw new Error("envelope: chunks must be an array");
  }
  for (const [i, chunk] of p.chunks.entries()) {
    if (!chunk || typeof chunk !== "object") {
      throw new Error(`envelope: chunks[${i}] is not an object`);
    }
    const c = chunk as Record<string, unknown>;
    if (typeof c.source !== "string") throw new Error(`envelope: chunks[${i}].source missing`);
    if (typeof c.text !== "string") throw new Error(`envelope: chunks[${i}].text missing`);
    if (
      c.curation !== "curated" &&
      c.curation !== "raw-excerpt" &&
      c.curation !== "session-excerpt" &&
      c.curation !== "heading-section"
    ) {
      throw new Error(`envelope: chunks[${i}].curation invalid`);
    }
    if (
      !Array.isArray(c.line_range) ||
      c.line_range.length !== 2 ||
      typeof c.line_range[0] !== "number" ||
      typeof c.line_range[1] !== "number"
    ) {
      throw new Error(`envelope: chunks[${i}].line_range must be [number, number]`);
    }
    if (c.node_id !== undefined && typeof c.node_id !== "string") {
      throw new Error(`envelope: chunks[${i}].node_id must be a string`);
    }
    if (
      c.heading_path !== undefined &&
      (!Array.isArray(c.heading_path) || c.heading_path.some((h) => typeof h !== "string"))
    ) {
      throw new Error(`envelope: chunks[${i}].heading_path must be string[]`);
    }
    if (c.node_kind !== undefined && c.node_kind !== "page" && c.node_kind !== "section") {
      throw new Error(`envelope: chunks[${i}].node_kind must be "page" or "section"`);
    }
  }
}

export function parseEnvelope(wire: string): Envelope {
  const nl = wire.indexOf("\n");
  if (nl < 0) throw new Error("envelope: missing length prefix");
  const prefix = wire.slice(0, nl);
  if (!/^\d+$/.test(prefix)) throw new Error(`envelope: malformed prefix: ${prefix}`);
  const declared = Number(prefix);
  const body = wire.slice(nl + 1);
  const actual = new TextEncoder().encode(body).length;
  if (actual !== declared) {
    throw new Error(`envelope: length mismatch (declared=${declared} actual=${actual})`);
  }
  const parsed: unknown = JSON.parse(body);
  assertValidShape(parsed);
  return parsed;
}
import { existsSync, realpathSync } from "node:fs";
import { join, relative } from "node:path";
import { defineCommand } from "citty";
import { resolveVaultPath } from "../lib/vault";
import { buildEnvelope, writeEnvelope, type EnvelopeChunk } from "../lib/envelope";
import { appendAccessLog } from "../lib/access-log";
import { assertGenuineScopeDir, PathUnsafeError } from "../lib/path-safety";
import { readWikiFileNoFollow, walkWiki } from "../lib/wiki-read";

const MAX_MATCHES = 20;
const CONTEXT_LINES = 3;

function grepFile(
  path: string,
  needle: string
): Array<{ lineStart: number; lineEnd: number; snippet: string }> {
  const contents = readWikiFileNoFollow(path);
  if (contents === null) return [];
  const lines = contents.split("\n");
  const needleLc = needle.toLowerCase();
  const hits: Array<{ lineStart: number; lineEnd: number; snippet: string }> = [];
  for (let i = 0; i < lines.length; i++) {
    if (lines[i]!.toLowerCase().includes(needleLc)) {
      const start = Math.max(0, i - CONTEXT_LINES);
      const end = Math.min(lines.length - 1, i + CONTEXT_LINES);
      hits.push({
        lineStart: start + 1,
        lineEnd: end + 1,
        snippet: lines.slice(start, end + 1).join("\n"),
      });
    }
  }
  return hits;
}

export default defineCommand({
  meta: { name: "recall", description: "Search curated wiki pages" },
  args: {
    query: { type: "positional", description: "Search query", required: true },
    vaultPath: { type: "string", description: "Path to the vault directory", alias: ["p"] },
  },
  async run({ args }) {
    const vaultPath = args.vaultPath ?? resolveVaultPath(process.cwd());

    if (!existsSync(vaultPath)) {
      process.stderr.write(`error: vault not found at ${vaultPath}\n`);
      process.exit(1);
    }

    const wikiDir = join(vaultPath, "wiki");
    if (!existsSync(wikiDir)) {
      process.stderr.write(`error: wiki directory missing at ${wikiDir}\n`);
      process.exit(1);
    }

    try {
      assertGenuineScopeDir(wikiDir, vaultPath);
    } catch (err) {
      if (err instanceof PathUnsafeError) {
        process.stderr.write(`error: ${err.message}\n`);
        process.exit(1);
      }
      throw err;
    }

    const wikiReal = realpathSync(wikiDir);
    const chunks: EnvelopeChunk[] = [];
    const query = args.query;

    walkWiki(wikiDir, wikiReal, (path) => {
      if (chunks.length >= MAX_MATCHES) return;
      const hits = grepFile(path, query);
      const rel = relative(vaultPath, path);
      for (const h of hits) {
        if (chunks.length >= MAX_MATCHES) break;
        chunks.push({
          source: rel,
          line_range: [h.lineStart, h.lineEnd],
          curation: "curated",
          text: h.snippet,
        });
      }
    });

    const policy =
      chunks.length === 0
        ? {
            trust: "curated" as const,
            source_scope: "wiki" as const,
            no_results: true,
            suggestions: ["Try: kb list-topics"],
          }
        : { trust: "curated" as const, source_scope: "wiki" as const };

    const wire = writeEnvelope(buildEnvelope({ policy, chunks }));
    process.stdout.write(wire);

    try {
      await appendAccessLog({
        vaultPath,
        command: "recall",
        query,
        pages_returned: chunks.length,
        bytes_returned: new TextEncoder().encode(wire).length,
        exit_code: 0,
      });
    } catch {
      // logging must never fail the command
    }
  },
});
